import React from "react";
import {
  Container,
  Divider,
  Heading,
  Box,
  Text,
  Tag,
  Link as ChakraLink,
} from "@chakra-ui/react";
import { Layout } from "../components/layout";
import { StaticImage } from "gatsby-plugin-image";
import { Link, navigate } from "gatsby";

const additionalProjects = [
  {
    title: "Cuentamiga Digital",
    description:
      "Banco Caja Social's first 100% digital savings account. I developed the complete frontend, helping the bank offer customers a fully digital account-opening experience.",
    technologies: ["Frontend development", "Digital banking"],
    url: "https://digital.bancocajasocial.com/cuentamiga/",
  },
  {
    title: "Banco Caja Social WhatsApp Service Channel",
    description:
      "A WhatsApp service channel for Banco Caja Social's individual customers. I developed the bot logic with Node.js and Genesys Cloud, and built the customer-facing experience with React, Next.js, and Tailwind CSS.",
    technologies: ["React", "Next.js", "Tailwind CSS", "Node.js", "Genesys Cloud"],
    url: "https://www.bancocajasocial.com/canales-alternos/whatsapp-de-servicio/",
  },
  {
    title: "Mi Pago Amigo",
    description:
      "A modernization of Banco Caja Social's payment platform, migrating from .NET to a new stack with a Next.js frontend and a NestJS backend.",
    technologies: [".NET", "Next.js", "NestJS"],
    url: "https://www.mipagoamigo.com/MPA_WebSite/ServicePayments",
  },
  {
    title: "SiAgéndalo",
    description:
      "A free online booking platform for service businesses, built entirely by me. Customers can book 24/7, with automatic WhatsApp reminders to help prevent missed appointments.",
    technologies: ["Next.js", "Node.js", "PostgreSQL"],
    url: "https://www.siagendalo.com/",
  },
];

const Proyects = () => {
  return (
    <Layout>
      <Box pt={{ base: 5, md: 10 }}>
        <Heading
          mt={10}
          textAlign={"left"}
          fontSize="3xl"
          color={"black"}
          mb={6}
        >
          Projects
        </Heading>
        <Box mb={5} borderRadius={"lg"} shadow={"md"} borderWidth={1}>
          <Box>
            <StaticImage
              src="../images/exportapp.png"
              alt="Exportapp project screenshot"
              quality={100}
              style={{
                border: "1px",
                borderTopLeftRadius: "20px",
                borderTopRightRadius: "20px",
                width: "100%",
              }}
            />
          </Box>
          <Box p={5}>
            <Heading
              mt={2}
              textAlign={"left"}
              fontSize="3xl"
              color={"black"}
              mb={6}
            >
              Exportapp
            </Heading>
            <Text fontSize={"xl"}>
              Exportapp helps small and medium-sized businesses in Colombia
              explore export options and assess the international potential of
              their products. I built the front end for this medium-fidelity
              prototype.
            </Text>

            <Box display={"flex"}  flexWrap={'wrap'} my={2}>
              <Tag mr={2} my={1}  size={"md"} variant="solid" colorScheme="linkedin">
                React.js
              </Tag>
              <Tag mr={2} my={1}  size={"md"} variant="solid" colorScheme="messenger">
                TypeScript
              </Tag>
              <Tag mr={2} my={1}  size={"md"} variant="solid" colorScheme="purple">
                Gatsby
              </Tag>
              <Tag mr={2} my={1}  size={"md"} variant="solid" colorScheme="teal">
                ChakraUI
              </Tag>
            </Box>
            <Divider mt={5} mb={3} />
            <ChakraLink
              _hover={{ color: "black" }}
              fontSize={"xl"}
              target="_blank"
              color="secondary.500"
              href="https://exportapp.lapix.com.co/"
            >
              Visit Website
            </ChakraLink>
          </Box>
        </Box>

        <Box my={8} borderRadius={"lg"} shadow={"md"} borderWidth={1}>
          <Box>
            <StaticImage
              src="../images/financenter.png"
              alt="Financenter project screenshot"
              quality={100}
              style={{
                border: "1px",
                borderTopLeftRadius: "20px",
                borderTopRightRadius: "20px",
                width: "100%",
              }}
            />
          </Box>
          <Box p={5}>
            <Heading
              mt={2}
              textAlign={"left"}
              fontSize="3xl"
              color={"black"}
              mb={6}
            >
              Financenter - Formulario crédito
            </Heading>
            <Text fontSize={"xl"}>
              I built a loan application form with Google reCAPTCHA validation
              for the financial institution Financenter.
            </Text>

            <Box display={"flex"}  flexWrap={'wrap'} my={2}>
              <Tag mr={2} my={1}  size={"md"} variant="solid" colorScheme="purple">
                Preact
              </Tag>
              <Tag mr={2} my={1}  size={"md"} variant="solid" colorScheme="messenger">
                TypeScript
              </Tag>
              <Tag mr={2} my={1}  size={"md"} variant="solid" colorScheme="teal">
                CSS
              </Tag>
              <Tag mr={2} my={1}  size={"md"} variant="solid" colorScheme="blackAlpha">
                reCAPTCHA
              </Tag>
            </Box>
            <Divider mt={5} mb={3} />
            <ChakraLink
              _hover={{ color: "black" }}
              fontSize={"xl"}
              target="_blank"
              color="secondary.500"
              href="https://www.financenter.com.co/"
            >
              Visit Website
            </ChakraLink>
          </Box>
        </Box>

        <Box my={8} borderRadius={"lg"} shadow={"md"} borderWidth={1}>
          <Box>
            <StaticImage
              src="../images/nomadu.png"
              alt="Nomadu learning platform screenshot"
              quality={100}
              style={{
                border: "1px",
                borderTopLeftRadius: "9px",
                borderTopRightRadius: "9px",
                width: "100%",
              }}
            />
          </Box>
          <Box p={5}>
            <Heading
              mt={2}
              textAlign={"left"}
              fontSize="3xl"
              color={"black"}
              mb={6}
            >
              Nomadu
            </Heading>
            <Text fontSize={"xl"}>
              An LMS platform for Colombian insurance companies. I built the
              front end for the student and administrator platforms, including
              modules for news, a dictionary, documents, courses, a dashboard,
              assessments, forums, and more.
            </Text>
            <Box display={"flex"}  flexWrap={'wrap'} my={2}>
            <Tag mr={2}  my={1}size={"md"} variant="solid" colorScheme="linkedin">
                React.js
              </Tag>
              <Tag mr={2} my={1} size={"md"} variant="solid" colorScheme="messenger">
                TypeScript
              </Tag>
              <Tag mr={2} my={1} size={"md"} variant="solid" colorScheme="purple">
                Gatsby
              </Tag>
              <Tag mr={2}my={1}  size={"md"} variant="solid" colorScheme="pink">
              GraphQL
              </Tag>
              <Tag mr={2} my={1} size={"md"} variant="solid" colorScheme="yellow">
               Firebase
              </Tag>
              <Tag mr={2}  my={1} size={"md"} variant="solid" colorScheme="teal">
                ChakraUI
              </Tag>
            </Box>
            <Divider mt={5} mb={3} />
            <ChakraLink
              _hover={{ color: "black" }}
              target="_blank"
              fontSize={"xl"}

              color="secondary.500"
              href="https://www.nomadu.com.co/"
            >
              Visit Website
            </ChakraLink>
          </Box>
        </Box>
        {additionalProjects.map((project) => (
          <Box key={project.title} my={8} borderRadius={"lg"} shadow={"md"} borderWidth={1}>
            <Box p={5}>
              <Heading
                mt={2}
                textAlign={"left"}
                fontSize="3xl"
                color={"black"}
                mb={6}
              >
                {project.title}
              </Heading>
              <Text fontSize={"xl"}>{project.description}</Text>
              <Box display={"flex"} flexWrap={"wrap"} my={2}>
                {project.technologies.map((technology) => (
                  <Tag
                    key={technology}
                    mr={2}
                    my={1}
                    size={"md"}
                    variant="solid"
                    colorScheme="linkedin"
                  >
                    {technology}
                  </Tag>
                ))}
              </Box>
              <Divider mt={5} mb={3} />
              <ChakraLink
                _hover={{ color: "black" }}
                fontSize={"xl"}
                target="_blank"
                rel="noopener noreferrer"
                color="secondary.500"
                href={project.url}
              >
                Visit Website
              </ChakraLink>
            </Box>
          </Box>
        ))}
      </Box>
    </Layout>
  );
};

export default Proyects;
